1	// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
2	// float.
3	package money
4	
5	import (
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// Currency is an ISO 4217 currency code.
13	type Currency string
14	
15	// The currencies Tally bills in.
16	const (
17		USD Currency = "USD"
18		EUR Currency = "EUR"
19		GBP Currency = "GBP"
20		JPY Currency = "JPY"
21		KWD Currency = "KWD"
22	)
23	
24	var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}
25	
26	// decimals is how many digits follow the decimal point in each currency's major unit (ISO 4217 minor unit).
27	var decimals = map[Currency]int{USD: 2, EUR: 2, GBP: 2, JPY: 0, KWD: 3}
28	
29	// Valid reports whether c is a currency Tally bills in.
30	func (c Currency) Valid() bool {
31		_, ok := symbols[c]
32		return ok
33	}
34	
35	// MinorUnits returns how many decimal places c has: 2 for USD ("12.50"), 0 for JPY ("1000"), 3 for KWD ("1.250").
36	// It returns 2 for a currency Tally does not bill in.
37	func (c Currency) MinorUnits() int {
38		if d, ok := decimals[c]; ok {
39			return d
40		}
41		return 2
42	}
43	
44	// ErrInvalidAmount is returned for an amount that cannot be read.
45	var ErrInvalidAmount = errors.New("invalid amount")
46	
47	// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1000" for JPY) and returns it in minor units.
48	// It accepts at most the currency's decimal places, and pads fewer.
49	func ParseMajor(s string, c Currency) (int64, error) {
50		if !c.Valid() {
51			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
52		}
53		d := c.MinorUnits()
54		s = strings.TrimSpace(s)
55		whole, frac, hasDot := strings.Cut(s, ".")
56		if whole == "" || (hasDot && (frac == "" || d == 0)) || len(frac) > d {
57			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
58		}
59		for _, r := range whole + frac {
60			if r < '0' || r > '9' {
61				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
62			}
63		}
64		for len(frac) < d {
65			frac += "0"
66		}
67		n, err := strconv.ParseInt(whole+frac, 10, 64)
68		if err != nil {
69			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
70		}
71		return n, nil
72	}
