74	// Format renders an amount for people, with the currency's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
75	func Format(amount int64, c Currency) string {
76		sign := ""
77		if amount < 0 {
78			sign, amount = "-", -amount
79		}
80		d := c.MinorUnits()
81		whole, frac := amount/pow10(d), amount%pow10(d)
82		if d == 0 {
83			return fmt.Sprintf("%s%s%s", sign, symbols[c], group(whole))
84		}
85		return fmt.Sprintf("%s%s%s.%0*d", sign, symbols[c], group(whole), d, frac)
86	}
87	
88	// FormatMajor renders an amount in major units with the currency's decimals and no symbol or thousands separator:
89	// "12.50", "1000" for JPY, "1.250" for KWD. It is the form ParseMajor reads back.
90	func FormatMajor(amount int64, c Currency) string {
91		sign := ""
92		if amount < 0 {
93			sign, amount = "-", -amount
94		}
95		d := c.MinorUnits()
96		whole, frac := amount/pow10(d), amount%pow10(d)
97		if d == 0 {
98			return fmt.Sprintf("%s%d", sign, whole)
99		}
100		return fmt.Sprintf("%s%d.%0*d", sign, whole, d, frac)
101	}
102	
103	// pow10 returns 10 to the power n, for n from 0 to 18.
104	func pow10(n int) int64 {
105		p := int64(1)
106		for i := 0; i < n; i++ {
107			p *= 10
108		}
109		return p
110	}
111	
112	// group writes n with a comma between each group of three digits.
113	func group(n int64) string {
114		s := strconv.FormatInt(n, 10)
115		var b strings.Builder
116		for i, r := range s {
117			if i > 0 && (len(s)-i)%3 == 0 {
118				b.WriteByte(',')
119			}
120			b.WriteRune(r)
121		}
122		return b.String()
123	}
124	
125	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
126	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
127	
128	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
129	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
130	
131	// divRound divides and rounds half away from zero.
132	func divRound(num, den int64) int64 {
133		if (num < 0) != (den < 0) {
134			return -((abs(num) + abs(den)/2) / abs(den))
135		}
136		return (abs(num) + abs(den)/2) / abs(den)
137	}
138	
139	func abs(v int64) int64 {
140		if v < 0 {
141			return -v
142		}
143		return v
144	}
